delete from prediction_scores
where prediction_id in (
  select predictions.id
  from predictions
  inner join matches on matches.id = predictions.match_id
  where matches.tournament_id = '11111111-1111-1111-1111-111111111111'
);

delete from predictions
where match_id in (
  select id
  from matches
  where tournament_id = '11111111-1111-1111-1111-111111111111'
);

delete from phase_deadlines
where league_tournament_id = '55555555-5555-5555-5555-555555555555';

delete from bonus_prediction_rules
where league_tournament_id = '55555555-5555-5555-5555-555555555555';

